import json
def handle(text):
    try:
        p=json.loads(text)
    except (json.JSONDecodeError,TypeError):
        p=None
    if not isinstance(p,dict):
        return json.dumps({'status':400,'errors':['тело запроса — не JSON-объект']},ensure_ascii=False)
    return json.dumps(predict_one(p),ensure_ascii=False)
