import pandas as pd
cuts=['2025-09-30','2025-12-31','2026-03-31']
def build_target(cutoff,months=3):
    c=pd.Timestamp(cutoff)
    active=base[(base.start_date<=c)&(base.end_date.isna()|(base.end_date>c))]
    end=c+pd.offsets.MonthEnd(months)
    if end>pd.Timestamp('2026-09-30'):
        return pd.Series(pd.NA,index=active.client_id.values,dtype='Int64',name='churn')
    return pd.Series((active.end_date.notna()&(active.end_date<=end)).astype(int).values,index=active.client_id.values,name='churn')
